using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorInspectorOperations
{
    private static Variant Invoke(Control owner,Variant callback,params Variant[] args)=>owner.Call("_invoke_inspector_callback",callback,new GArray(args));
    private static bool Empty(Variant value)=>value.VariantType==Variant.Type.Nil||value.VariantType==Variant.Type.String&&value.AsString().Length==0;
    public void add_file_resource_slot(Control owner,Control parent,Resource property,Variant getValue,Variant setValue,Variant expand,Variant parameters)
    {
        var slot=new ActorResourceSlot();slot.Name=property.Get("id").AsString()+"_file";slot.Alignment=HorizontalAlignment.Left;slot.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;owner.Call("_configure_file_slot_validation",slot,property);parent.AddChild(slot);Button? editShader=null,editImage=null;if(property.Get("id").AsString()=="mesh_path"){var edit=new Button{Text="Model ↗",TooltipText="Open an editable copy in the 3D Modeling Workspace"};parent.AddChild(edit);edit.Pressed+=()=>{var value=Invoke(owner,getValue);if(value.VariantType==Variant.Type.String&&value.AsString().Length>0)owner.GetTree().GetFirstNodeInGroup("actor_scene_tabs")?.Call("open_model",value);};var unique=new Button{Text="Unique…",TooltipText="Save an independent model asset for this actor only"};parent.AddChild(unique);unique.Pressed+=()=>owner.Call("_make_model_unique",getValue,setValue);}if(is_shader_property(property)){editShader=new Button{Name=property.Get("id").AsString()+"_open_workspace",Text="Edit ↗",TooltipText="Open this shader in a full shader editor tab",CustomMinimumSize=new Vector2(66,0)};parent.AddChild(editShader);editShader.Pressed+=()=>{var source=Invoke(owner,getValue);if(!Empty(source))open_shader_resource(owner,source,true,Invoke(owner,parameters));};}if(!is_shader_property(property)&&Extensions(property).Contains("png")){editImage=new Button{Name=property.Get("id").AsString()+"_open_image_workspace",Text="Edit ↗",TooltipText="Open this image in an image editor tab",CustomMinimumSize=new Vector2(66,0)};parent.AddChild(editImage);editImage.Pressed+=()=>open_image_workspace(owner,Invoke(owner,getValue));}var menu=new PopupMenu();slot.AddChild(menu);string type=file_resource_type_name(property);menu.AddItem("Copy to Super Clipboard",6);menu.AddItem("Load from Super Clipboard…",7);menu.AddItem("New "+type,0);bool audio=Extensions(property).Any(e=>e is "mp3" or "mp4");menu.SetItemDisabled(menu.GetItemIndex(0),audio);if(property.Get("options").AsGodotDictionary().GetValueOrDefault("shader_texture",false).AsBool())menu.AddItem("New Noise Image",5);menu.AddItem("Load from project…",1);menu.AddSeparator();menu.AddItem("Make Unique",2);menu.AddItem("Save As…",3);menu.AddSeparator();menu.AddItem("Clear",4);
        void Update(){var value=Invoke(owner,getValue);bool empty=Empty(value);slot.Text="▸  "+type+(empty?"  <empty>":"  "+file_resource_display_name(value));slot.TooltipText=empty?"Drop a compatible project file here":file_resource_tooltip(value);menu.SetItemDisabled(menu.GetItemIndex(2),audio||empty||value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource);foreach(int id in new[]{3,6,4})menu.SetItemDisabled(menu.GetItemIndex(id),empty);if(GodotObject.IsInstanceValid(editShader))editShader!.Visible=!empty;if(GodotObject.IsInstanceValid(editImage)){bool supported=value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Texture2D or Image;if(value.VariantType==Variant.Type.String)supported=ImageExtensions.Contains(value.AsString().GetExtension().ToLowerInvariant());if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource reference&&ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd")){var data=owner.Call("_resolve_object",reference).As<Resource>();var source=data!=null?_data.object_get_value(data,"source",""):default;supported=data!=null&&data.Get("type_id").AsString()=="image"&&source.VariantType!=Variant.Type.Nil&&source.ToString().Length>0;}editImage!.Visible=!empty&&supported;}}
        Update();void Show(Vector2 position){Update();menu.Position=new Vector2I((int)position.X,(int)position.Y);menu.Popup();}slot.Pressed+=()=>{var value=Invoke(owner,getValue);var expanded=Invoke(owner,expand);if(expanded.VariantType==Variant.Type.Bool&&expanded.AsBool())return;if(is_shader_property(property)&&!Empty(value))open_shader_resource(owner,value,false,default);else Show(slot.GetScreenPosition()+new Vector2(0,slot.Size.Y));};slot.GuiInput+=ev=>{if(ev is InputEventMouseButton mouse&&mouse.Pressed&&mouse.ButtonIndex==MouseButton.Right){Show(mouse.GlobalPosition);owner.GetViewport().SetInputAsHandled();}};slot.Connect("file_dropped",Callable.From<string>(path=>{Invoke(owner,setValue,path);if(is_shader_property(property))open_shader_resource(owner,path,false,default);}));var update=Callable.From(Update);menu.IdPressed+=id=>owner.Call("_file_resource_menu_action",id,property,getValue,setValue,update);owner.Get("_updaters").AsGodotArray().Add(update);
    }
}
